import{_ as t,o as n,c as r,ag as s}from"./chunks/framework.BRIULxAp.js";const g=JSON.parse(`{"title":"Au-delà du poste (pour aller plus loin)","description":"","frontmatter":{},"headers":[],"relativePath":"handout-11-au-dela-du-poste.md","filePath":"handout-11-au-dela-du-poste.md","handout":{"fichier":"handout-11-au-dela-du-poste.md","markdown":"# Handout — Au-delà du poste (pour aller plus loin)\\n\\n**Développeur IA — Avancé · Zenika · fiche de référence**\\n\\nCe que change l'agent pour l'entreprise, au-delà du poste du dev : guardrails, AI gateway, budget caché, réversibilité, revue à trois. Ces slides ont quitté le deck de la formation (la gouvernance est traitée côté tech managers, dans la formation « Le nouveau PDLC IA ») ; la fiche reste comme référence, à lire seul.\\n\\n## Où placer les contrôles\\n\\n_Slide retirée du deck · pour aller plus loin : « Où placer les contrôles »_\\n\\n| Garde               | Ce qu'elle contrôle                                                                                 |\\n| ------------------- | --------------------------------------------------------------------------------------------------- |\\n| **Garde d'entrée**  | injection, jailbreak ; données perso, secrets → masquer ; sujets interdits ; taille, débit, budget  |\\n| **Garde de sortie** | toxicité, hors périmètre ; fuite de données ; ancrage (grounding) ; format / schéma valide          |\\n| **Garde d'action**  | liste blanche de tools ; sandbox, conteneur, réseau ; droits minimaux (tokens) ; validation humaine |\\n\\n> Les gardes d'entrée et de sortie **réduisent** le risque. La garde d'action le **borne** : un agent sans réseau ne peut pas exfiltrer.\\n\\n- Défense en profondeur : aucun étage n'est suffisant seul.\\n- Les gardes d'entrée et de sortie sont souvent elles-mêmes des modèles (classifieurs, petits modèles), donc faillibles, avec de la latence et du coût. On les place sur les données externes non fiables (prompt injection) et sur les sorties qui partent vers des clients.\\n- La garde d'action est déterministe : un refus sur \`git push\` ne se contourne pas par un prompt astucieux. Pour un agent de code, c'est le premier investissement : permissions du harness, sandbox ou conteneur, tokens à portée minimale.\\n- **Trio létal** : données privées + contenu non fiable + capacité d'envoyer vers l'extérieur. Casser un des trois, c'est le rôle de la garde d'action.\\n\\n## L'AI gateway : un seul point de passage\\n\\n_Slide retirée du deck · pour aller plus loin : « L'AI gateway : un seul point de passage »_\\n\\nUn **proxy entre vos agents et les fournisseurs de modèles** : une seule API côté agents, N fournisseurs derrière, aucune clé de fournisseur sur les postes.\\n\\n| Fonction          | Ce qu'elle apporte                                           |\\n| ----------------- | ------------------------------------------------------------ |\\n| **Routage**       | choix du modèle, **fallback** si un fournisseur tombe        |\\n| **FinOps**        | quotas et **plafond de dépense** par équipe                  |\\n| **Observabilité** | tokens, coût et latence par appel (souvent en OpenTelemetry) |\\n| **Emballement**   | coupe l'agent coincé dans une boucle                         |\\n| **Guardrails**    | masquage, détection d'injection : appliqués **à tous**       |\\n| **Traçabilité**   | modèles autorisés, résidence des données, audit              |\\n\\n- La gouvernance sans modifier les agents : ajouter un masquage ou changer de fournisseur se fait dans la gateway, une fois.\\n- Le **plafond de dépense** est le garde-fou le plus simple, à poser dans la gateway.\\n- Attention au **cache sémantique** de certaines gateways : il renvoie une réponse déjà générée pour une question « proche ». Utile pour une FAQ, dangereux pour un agent de code. À ne pas confondre avec le **prompt caching** du fournisseur (module 1), qui ne change pas la réponse.\\n\\n## Le budget caché : au-delà des tokens\\n\\n_Slide retirée du deck · pour aller plus loin : « Le budget caché : au-delà des tokens »_\\n\\nPlus d'agents, c'est plus de PR. Donc plus de **builds**, de **tests**, de **mutation testing** : la facture est **double**, les tokens et les **runners CI**.\\n\\n| Étape                 | Effet                                |\\n| --------------------- | ------------------------------------ |\\n| Adoption des agents   | plus de travail en parallèle         |\\n| Multiplication des PR | plus de CI, de tests, de mutation    |\\n| Résultat              | facture tokens **+** facture runners |\\n\\n> Un budget IA, c'est **tokens + CI + stockage + temps de revue**. Le temps de revue humaine est le poste le plus oublié, et c'est lui qui limite le parallélisme.\\n\\n## Réversibilité : éviter le vendor lock-in\\n\\n_Slide retirée du deck · pour aller plus loin : « Réversibilité : éviter le vendor lock-in »_\\n\\n| Principe                  | Pourquoi                                                                         |\\n| ------------------------- | -------------------------------------------------------------------------------- |\\n| **Harness ≠ fournisseur** | l'adhérence est dans le harness ; les modèles changent tous les trimestres       |\\n| **Modèle via la gateway** | basculer sans réécrire l'outillage                                               |\\n| **Formats ouverts**       | \`AGENTS.md\`, \`SKILL.md\`, MCP survivent à un changement d'outil                   |\\n| **Résidence des données** | à exiger au contrat : aucune donnée ne sert au réentraînement, hébergement connu |\\n\\nModèle via la gateway : les agents appellent un nom interne (ex. \`code-standard\`), la gateway choisit le modèle réel derrière. Changer de modèle devient un réglage côté gateway, à condition que le harness accepte une adresse d'API personnalisée.\\n\\nChoisir un harness, un modèle, un fournisseur : trois décisions désormais séparables, selon trois postures.\\n\\n| Posture                     | Exemples                                                                                            | Ce que ça implique                                                                                                  |\\n| --------------------------- | --------------------------------------------------------------------------------------------------- | ------------------------------------------------------------------------------------------------------------------- |\\n| **Mono-fournisseur**        | Claude Code                                                                                         | le harness impose la famille de modèles : cohérence maximale, arbitrage impossible ; l'hébergement reste négociable |\\n| **Catalogue multi-éditeur** | GitHub Copilot                                                                                      | un contrat, plusieurs modèles au choix en session : arbitrage coût / puissance sans changer d'outil                 |\\n| **Agnostique**              | OpenCode, Pi, Aider ; Codex par configuration (fournisseurs compatibles API OpenAI, modèles locaux) | le fournisseur est un paramètre : liberté totale, intégration (permissions, support) à votre charge                 |\\n\\n> **Tip du module** : Tracé et portable : un agent qu'on peut **auditer**, et **quitter**. Commits tracés, specs versionnées, appels journalisés par la gateway, formats ouverts.\\n\\n## Pair-programming à trois\\n\\n_Slide retirée du deck · pour aller plus loin : « Pair-programming à trois »_\\n\\nLe dev et un relecteur (deux personnes) + l'agent de revue, **en même temps**.\\n\\n| Cycle de PR asynchrone                    | 2 personnes + 1 agent, en synchrone                      |\\n| ----------------------------------------- | -------------------------------------------------------- |\\n| 1. Le dev soumet la PR                    | 1. L'agent de revue (CI) produit son rapport             |\\n| 2. Le relecteur commente (24 h d'attente) | 2. Le dev et le relecteur trient les remarques en direct |\\n| 3. Le dev corrige (12 h d'attente)        | 3. L'agent applique les corrections                      |\\n\\n> Moins d'attente, des retours plus pertinents, une validation immédiate. Et un moment où la connaissance circule.\\n\\n## À retenir\\n\\n1. La **garde d'action** borne le risque, les gardes d'entrée et de sortie le réduisent.\\n2. La **gateway** route, plafonne, observe et trace, pour toute l'entreprise.\\n3. Un budget IA compte aussi la **CI** et le **temps de revue**.\\n4. Un agent tracé et portable : on peut l'**auditer**, et le **quitter**.\\n\\n**Mots-clés** : guardrails, gateway, prompt injection, trio létal, plafond de dépense, vendor lock-in, human-in-the-loop — voir le glossaire.\\n"}}`),a={name:"handout-11-au-dela-du-poste.md"};function o(l,e,i,d,u,c){return n(),r("div",null,[...e[0]||(e[0]=[s('<p class="zh-type">fiche de référence</p><h1 id="handout-au-dela-du-poste" tabindex="-1">Au-delà du poste (pour aller plus loin) <a class="header-anchor" href="#handout-au-dela-du-poste" aria-label="Permalink to &quot;Handout — Au-delà du poste (pour aller plus loin)&quot;">​</a></h1><p>Ce que change l’agent pour l’entreprise, au-delà du poste du dev : guardrails, AI gateway, budget caché, réversibilité, revue à trois. Ces slides ont quitté le deck de la formation (la gouvernance est traitée côté tech managers, dans la formation « Le nouveau PDLC IA ») ; la fiche reste comme référence, à lire seul.</p><h2 id="ou-placer-les-controles" tabindex="-1">Où placer les contrôles <a class="header-anchor" href="#ou-placer-les-controles" aria-label="Permalink to &quot;Où placer les contrôles&quot;">​</a></h2><p><em>Slide retirée du deck · pour aller plus loin : « Où placer les contrôles »</em></p><table tabindex="0"><thead><tr><th>Garde</th><th>Ce qu’elle contrôle</th></tr></thead><tbody><tr><td><strong>Garde d’entrée</strong></td><td>injection, jailbreak ; données perso, secrets → masquer ; sujets interdits ; taille, débit, budget</td></tr><tr><td><strong>Garde de sortie</strong></td><td>toxicité, hors périmètre ; fuite de données ; ancrage (grounding) ; format / schéma valide</td></tr><tr><td><strong>Garde d’action</strong></td><td>liste blanche de tools ; sandbox, conteneur, réseau ; droits minimaux (tokens) ; validation humaine</td></tr></tbody></table><blockquote><p>Les gardes d’entrée et de sortie <strong>réduisent</strong> le risque. La garde d’action le <strong>borne</strong> : un agent sans réseau ne peut pas exfiltrer.</p></blockquote><ul><li>Défense en profondeur : aucun étage n’est suffisant seul.</li><li>Les gardes d’entrée et de sortie sont souvent elles-mêmes des modèles (classifieurs, petits modèles), donc faillibles, avec de la latence et du coût. On les place sur les données externes non fiables (prompt injection) et sur les sorties qui partent vers des clients.</li><li>La garde d’action est déterministe : un refus sur <code>git push</code> ne se contourne pas par un prompt astucieux. Pour un agent de code, c’est le premier investissement : permissions du harness, sandbox ou conteneur, tokens à portée minimale.</li><li><strong>Trio létal</strong> : données privées + contenu non fiable + capacité d’envoyer vers l’extérieur. Casser un des trois, c’est le rôle de la garde d’action.</li></ul><h2 id="l-ai-gateway-un-seul-point-de-passage" tabindex="-1">L’AI gateway : un seul point de passage <a class="header-anchor" href="#l-ai-gateway-un-seul-point-de-passage" aria-label="Permalink to &quot;L&#39;AI gateway : un seul point de passage&quot;">​</a></h2><p><em>Slide retirée du deck · pour aller plus loin : « L’AI gateway : un seul point de passage »</em></p><p>Un <strong>proxy entre vos agents et les fournisseurs de modèles</strong> : une seule API côté agents, N fournisseurs derrière, aucune clé de fournisseur sur les postes.</p><table tabindex="0"><thead><tr><th>Fonction</th><th>Ce qu’elle apporte</th></tr></thead><tbody><tr><td><strong>Routage</strong></td><td>choix du modèle, <strong>fallback</strong> si un fournisseur tombe</td></tr><tr><td><strong>FinOps</strong></td><td>quotas et <strong>plafond de dépense</strong> par équipe</td></tr><tr><td><strong>Observabilité</strong></td><td>tokens, coût et latence par appel (souvent en OpenTelemetry)</td></tr><tr><td><strong>Emballement</strong></td><td>coupe l’agent coincé dans une boucle</td></tr><tr><td><strong>Guardrails</strong></td><td>masquage, détection d’injection : appliqués <strong>à tous</strong></td></tr><tr><td><strong>Traçabilité</strong></td><td>modèles autorisés, résidence des données, audit</td></tr></tbody></table><ul><li>La gouvernance sans modifier les agents : ajouter un masquage ou changer de fournisseur se fait dans la gateway, une fois.</li><li>Le <strong>plafond de dépense</strong> est le garde-fou le plus simple, à poser dans la gateway.</li><li>Attention au <strong>cache sémantique</strong> de certaines gateways : il renvoie une réponse déjà générée pour une question « proche ». Utile pour une FAQ, dangereux pour un agent de code. À ne pas confondre avec le <strong>prompt caching</strong> du fournisseur (module 1), qui ne change pas la réponse.</li></ul><h2 id="le-budget-cache-au-dela-des-tokens" tabindex="-1">Le budget caché : au-delà des tokens <a class="header-anchor" href="#le-budget-cache-au-dela-des-tokens" aria-label="Permalink to &quot;Le budget caché : au-delà des tokens&quot;">​</a></h2><p><em>Slide retirée du deck · pour aller plus loin : « Le budget caché : au-delà des tokens »</em></p><p>Plus d’agents, c’est plus de PR. Donc plus de <strong>builds</strong>, de <strong>tests</strong>, de <strong>mutation testing</strong> : la facture est <strong>double</strong>, les tokens et les <strong>runners CI</strong>.</p><table tabindex="0"><thead><tr><th>Étape</th><th>Effet</th></tr></thead><tbody><tr><td>Adoption des agents</td><td>plus de travail en parallèle</td></tr><tr><td>Multiplication des PR</td><td>plus de CI, de tests, de mutation</td></tr><tr><td>Résultat</td><td>facture tokens <strong>+</strong> facture runners</td></tr></tbody></table><blockquote><p>Un budget IA, c’est <strong>tokens + CI + stockage + temps de revue</strong>. Le temps de revue humaine est le poste le plus oublié, et c’est lui qui limite le parallélisme.</p></blockquote><h2 id="reversibilite-eviter-le-vendor-lock-in" tabindex="-1">Réversibilité : éviter le vendor lock-in <a class="header-anchor" href="#reversibilite-eviter-le-vendor-lock-in" aria-label="Permalink to &quot;Réversibilité : éviter le vendor lock-in&quot;">​</a></h2><p><em>Slide retirée du deck · pour aller plus loin : « Réversibilité : éviter le vendor lock-in »</em></p><table tabindex="0"><thead><tr><th>Principe</th><th>Pourquoi</th></tr></thead><tbody><tr><td><strong>Harness ≠ fournisseur</strong></td><td>l’adhérence est dans le harness ; les modèles changent tous les trimestres</td></tr><tr><td><strong>Modèle via la gateway</strong></td><td>basculer sans réécrire l’outillage</td></tr><tr><td><strong>Formats ouverts</strong></td><td><code>AGENTS.md</code>, <code>SKILL.md</code>, MCP survivent à un changement d’outil</td></tr><tr><td><strong>Résidence des données</strong></td><td>à exiger au contrat : aucune donnée ne sert au réentraînement, hébergement connu</td></tr></tbody></table><p>Modèle via la gateway : les agents appellent un nom interne (ex. <code>code-standard</code>), la gateway choisit le modèle réel derrière. Changer de modèle devient un réglage côté gateway, à condition que le harness accepte une adresse d’API personnalisée.</p><p>Choisir un harness, un modèle, un fournisseur : trois décisions désormais séparables, selon trois postures.</p><table tabindex="0"><thead><tr><th>Posture</th><th>Exemples</th><th>Ce que ça implique</th></tr></thead><tbody><tr><td><strong>Mono-fournisseur</strong></td><td>Claude Code</td><td>le harness impose la famille de modèles : cohérence maximale, arbitrage impossible ; l’hébergement reste négociable</td></tr><tr><td><strong>Catalogue multi-éditeur</strong></td><td>GitHub Copilot</td><td>un contrat, plusieurs modèles au choix en session : arbitrage coût / puissance sans changer d’outil</td></tr><tr><td><strong>Agnostique</strong></td><td>OpenCode, Pi, Aider ; Codex par configuration (fournisseurs compatibles API OpenAI, modèles locaux)</td><td>le fournisseur est un paramètre : liberté totale, intégration (permissions, support) à votre charge</td></tr></tbody></table><blockquote><p><strong>Tip du module</strong> : Tracé et portable : un agent qu’on peut <strong>auditer</strong>, et <strong>quitter</strong>. Commits tracés, specs versionnées, appels journalisés par la gateway, formats ouverts.</p></blockquote><h2 id="pair-programming-a-trois" tabindex="-1">Pair-programming à trois <a class="header-anchor" href="#pair-programming-a-trois" aria-label="Permalink to &quot;Pair-programming à trois&quot;">​</a></h2><p><em>Slide retirée du deck · pour aller plus loin : « Pair-programming à trois »</em></p><p>Le dev et un relecteur (deux personnes) + l’agent de revue, <strong>en même temps</strong>.</p><table tabindex="0"><thead><tr><th>Cycle de PR asynchrone</th><th>2 personnes + 1 agent, en synchrone</th></tr></thead><tbody><tr><td>1. Le dev soumet la PR</td><td>1. L’agent de revue (CI) produit son rapport</td></tr><tr><td>2. Le relecteur commente (24 h d’attente)</td><td>2. Le dev et le relecteur trient les remarques en direct</td></tr><tr><td>3. Le dev corrige (12 h d’attente)</td><td>3. L’agent applique les corrections</td></tr></tbody></table><blockquote><p>Moins d’attente, des retours plus pertinents, une validation immédiate. Et un moment où la connaissance circule.</p></blockquote><h2 id="a-retenir" tabindex="-1">À retenir <a class="header-anchor" href="#a-retenir" aria-label="Permalink to &quot;À retenir&quot;">​</a></h2><ol><li>La <strong>garde d’action</strong> borne le risque, les gardes d’entrée et de sortie le réduisent.</li><li>La <strong>gateway</strong> route, plafonne, observe et trace, pour toute l’entreprise.</li><li>Un budget IA compte aussi la <strong>CI</strong> et le <strong>temps de revue</strong>.</li><li>Un agent tracé et portable : on peut l’<strong>auditer</strong>, et le <strong>quitter</strong>.</li></ol><p><strong>Mots-clés</strong> : guardrails, gateway, prompt injection, trio létal, plafond de dépense, vendor lock-in, human-in-the-loop — voir le glossaire.</p>',33)])])}const m=t(a,[["render",o]]);export{g as __pageData,m as default};
